// Ported from the Node app's Sequelize model User (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class UserConfiguration : IEntityTypeConfiguration<User>
{
    public void Configure(EntityTypeBuilder<User> builder)
    {
        builder.ToTable("users", t =>
        {
            t.HasCheckConstraint("CK_users_role", "[role] IN (N'admin', N'teacher', N'accountant', N'parent', N'student')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(100)").HasMaxLength(100).IsRequired();
        builder.Property(e => e.Email).HasColumnName("email").HasColumnType("nvarchar(150)").HasMaxLength(150).IsRequired();
        builder.Property(e => e.PasswordHash).HasColumnName("password_hash").HasColumnType("nvarchar(255)").HasMaxLength(255).IsRequired();
        builder.Property(e => e.RoleId).HasColumnName("role_id");
        builder.Property(e => e.StaffId).HasColumnName("staff_id");
        builder.Property(e => e.MustChangePassword).HasColumnName("must_change_password");
        builder.Property(e => e.Role).HasColumnName("role").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'admin'");
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
        builder.HasIndex(e => e.Email).IsUnique();
        builder.HasOne(e => e.RoleNavigation).WithMany(p => p.Users).HasForeignKey(e => e.RoleId).OnDelete(DeleteBehavior.NoAction);
    }
}
